'use strict';
// Original instructional draft. Automated checks are NOT human content approval.
const C = require('../index');
const questions = require('./python-questions');
const SOURCE_COMMIT = '42155a0feaca9ba6991942c323cbe9fb7278be3c';
const refs = {
  introduction: 'Doc/tutorial/introduction.rst', controlflow: 'Doc/tutorial/controlflow.rst',
  datastructures: 'Doc/tutorial/datastructures.rst', errors: 'Doc/tutorial/errors.rst',
  inputoutput: 'Doc/tutorial/inputoutput.rst', modules: 'Doc/tutorial/modules.rst',
  functions: 'Doc/tutorial/controlflow.rst', types: 'Doc/reference/datamodel.rst', csv: 'Doc/library/csv.rst',
};
const lessons = [];
function add(id, comp, title, introduction, sections, worked, mistakes, takeaways, references, reuseLevels) {
  const competency = C.competency('python-fundamentals.' + comp);
  lessons.push({ id, module: competency.module, version: 1, title, minutes: 35,
    objectives: [{ id: 'python-fundamentals.' + comp, text: competency.competency.text }],
    prerequisites: lessons.length ? [lessons[lessons.length - 1].id] : [],
    prerequisite_note: lessons.length ? 'Review the preceding lesson if any names or notation are unfamiliar. You can revisit it at any time.' : 'No Python experience is needed. The opening section explains programs, names, values and output. Programming Foundations is the canonical prerequisite roadmap. Its outline identifies background topics; this opening lesson supplies a basic Python notation bridge.',
    introduction, sections, worked, mistakes, takeaways, references,
    reuse: reuseLevels.map(level => ({ track: 'cs104-python', level, relationship: 'supplementary_practice' })),
    quiz: questions[id].slice(0, 3).map(q => q.id),
  });
}
add('py-arithmetic', 'm1.c1', 'From named values to reliable arithmetic',
  'A program is a sequence of instructions that transforms information. An inventory application might receive a number of items and calculate a packing requirement. Python lets us express that calculation using readable names and operators. You will start with a complete small program, then learn why choosing the right arithmetic operation matters. All businesses and data in this course are hypothetical.',
  [
    { heading: 'Run a small program and follow its state', paragraphs: [
      'A Python source file contains plain text instructions. An interpreter executes them. In an interactive shell, a typed expression can display its value; in a script, use print(...) to display a value explicitly. Text in quotes is a string. A number without quotes can participate in arithmetic. A line beginning with # is a comment for readers, not an instruction.',
      'The assignment boxes = 17 binds the name boxes to an integer object. Read = as “assign”, not a mathematical promise that must remain true. A later boxes = boxes + 1 evaluates the right-hand side using the old value, then rebinds the name. Python distinguishes uppercase and lowercase names. Keep indentation consistent: indented statements belong to a surrounding block, which later lessons use for decisions and loops.'
    ] },
    { heading: 'Choose the operation that matches the requirement', paragraphs: [
      'Addition (+), subtraction (-) and multiplication (*) work as expected for numbers. Exponentiation is **. Parentheses make an intended grouping explicit; otherwise multiplication and division bind more tightly than addition and subtraction. Ordinary division / produces a floating-point result even when its operands are integers: 8 / 4 is 2.0. Floor division // rounds the quotient down toward negative infinity, so -7 // 3 is -3, not -2.',
      'Modulo % gives the remainder that makes a == (a // b) * b + a % b true for nonzero b. For positive item counts and a positive pack size, // counts full packs and % counts leftovers. With negative operands, do not import a truncation rule from another language: -7 % 3 is 2. Dividing or taking a remainder by zero raises ZeroDivisionError. Validate a denominator rather than assuming input can never be zero.'
    ], table: { headers: ['Expression', 'Result', 'Meaning'], rows: [['17 // 5','3','Three full packs'],['17 % 5','2','Two items remain'],['17 / 5','3.4','An ordinary quotient'],['-7 // 3','-3','Floor toward negative infinity']] } },
    { heading: 'Understand the limits of floating-point values', paragraphs: [
      'Python integers represent whole numbers with arbitrary precision subject to available memory. A float represents an approximation using a finite binary representation. Many decimal fractions have no exact binary representation: 0.1 + 0.2 is not exactly 0.3. This is representation error, not random arithmetic. Use math.isclose for a tolerance-based numerical comparison; choose tolerances that fit the units and scale.',
      'Formatting a value to two decimal places changes its displayed text, not the underlying calculation. Financial requirements may call for integer minor units or decimal.Decimal constructed from strings, with an explicit rounding policy. Do not turn a displayed rounded price back into a float and assume you have implemented money correctly. This lesson uses whole-item counts to keep business rules exact.'
    ] }
  ],
  { problem: 'A warehouse must pack 17 units into cartons holding 5 each. Report full cartons, loose units and the total cartons if every unit must be shipped.', steps: ['Bind the count and capacity to integers. Capacity must be positive for this packing model.','Use floor division for full cartons and modulo for the leftover units.','Add one carton only if a remainder exists; bool-to-int conversion is explained in the type-conversion lesson.'], code: 'units = 17\ncapacity = 5\nfull, loose = divmod(units, capacity)\ncartons = full + (1 if loose else 0)\nprint(full, loose, cartons)', expect: '3 2 4', explanation: 'Three cartons hold 15 units, two units need a fourth carton. divmod returns the quotient and remainder together: full receives the quotient and loose receives the remainder. The conditional expression selects 1 for a nonzero remainder and 0 otherwise. No floating-point rounding is involved.' },
  ['Using / when a count of full groups is required produces a fractional result. Match the operator to the business rule.','Assuming // truncates toward zero gives wrong predictions for negative values.','Using == to compare computed decimal fractions may reject a numerically close result. Choose a tolerance or an appropriate exact representation.'],
  ['Assignment binds names to values; print displays a result in a script.','Floor division and modulo answer different grouping questions.','Binary floats approximate many decimal fractions; display formatting is not a precision policy.'], ['introduction','types','functions'], [1,2]);

add('py-strings', 'm1.c2', 'Extracting and presenting text safely',
  'Student identifiers, order references and support messages arrive as text. A string is an immutable sequence of Unicode characters. Immutability means operations create a new string rather than editing the original object. This lesson explains how positions, slices, normalization and formatting solve different parts of a text-processing requirement.',
  [
    { heading: 'Positions and slices have different boundary rules', paragraphs: [
      'Indexing selects one character. Positions start at zero, so code[0] selects the first character. Negative positions count from the end: code[-1] is the last character. Indexing outside a string raises IndexError; an empty string has no valid index. A Unicode character is not necessarily a whole visible symbol: some displayed characters combine multiple code points. Basic slicing is not a full text-layout operation.',
      'A slice text[start:stop:step] selects positions from start up to, but excluding, stop. Omitted bounds choose the relevant end. A negative step traverses backward; text[::-1] reverses code points. Slices clamp ordinary out-of-range bounds instead of raising IndexError, but a step of zero raises ValueError. Do not rely on a fixed slice position unless the input format is actually guaranteed.'
    ] },
    { heading: 'Normalize only what the requirement permits', paragraphs: [
      'strip() removes whitespace from both ends, not from the middle. lower() and casefold() return transformed strings; casefold is designed for caseless matching. These methods do not alter the variable unless you assign their returned value. split(separator) returns pieces and join combines a sequence of strings using a separator. With no separator, split() handles runs of whitespace differently from split(" ").',
      'Normalization is a business decision. Lowercasing a case-sensitive secret or an identifier whose case matters changes its meaning. A support-search key may be casefolded while preserving the original message for display. Keep original input when auditability matters. A method named replace performs text replacement, not validation of whether a record is trustworthy.'
    ] },
    { heading: 'Separate formatted display from stored values', paragraphs: [
      'An f-string begins with f before its quote and evaluates expressions inside braces. A format specifier follows a colon: f"{price:.2f}" displays two decimal places. Strings concatenate with + only when both operands are strings; str(number) converts a value for text use. An f-string is often clearer than repeated conversion and concatenation.',
      'Python text formatting does not automatically escape HTML, SQL, shell syntax or other output languages. Use a web framework’s escaping and parameterized database queries at those boundaries. Do not use eval to interpret a user’s text. The example below only normalizes a known synthetic reference format; production code would validate the structure before slicing.'
    ] }
  ],
  { problem: 'An LMS receives an order reference with accidental surrounding spaces. Display its prefix, numeric suffix and a normalized search key while preserving the received value.', steps: ['Retain the original string for traceability.','Strip surrounding whitespace into a new variable, then split the known prefix and suffix using slices.','Use an f-string for a readable display; build a separate case-insensitive search key.'], code: 'received = "  ENR-0042  "\nreference = received.strip()\nprefix, number = reference[:3], reference[4:]\nprint(f"{prefix}: {number}")\nprint(reference.casefold())\nprint(received == reference)', expect: 'ENR: 0042\nenr-0042\nFalse', explanation: 'The slice ending at position 3 excludes the hyphen. Starting at position 4 keeps the leading zeroes in the suffix because it remains text. strip returned a new string; the preserved received value still contains spaces.' },
  ['Assigning text[0] = "A" fails because a string is immutable; build a new string instead.','Including the stop position in a slice prediction is an off-by-one error.','Calling strip() without using its return value leaves the original binding unchanged.'],
  ['Indexing can fail where slicing safely returns fewer characters.','String methods return new values, so retain their results when needed.','Formatting and normalization do not replace boundary-specific escaping or validation.'], ['introduction','types'], [4]);

add('py-conversions', 'm1.c3', 'Converting input without changing its meaning',
  'An appointment form can submit the text "12" even when a business rule expects a count. A type tells Python which operations a value supports; conversion creates a value of another type when a valid conversion exists. A reliable program checks both whether a conversion is possible and whether the resulting value makes sense for the requirement.',
  [
    { heading: 'Text input is not already a number', paragraphs: [
      'input(...) reads a line and returns a string, without the ending newline. int("12") produces the integer 12, while float("12.5") produces a float. str(12) produces display text. A constructor is not a universal parser: int("12.5") raises ValueError because the decimal string is not integer notation. int(12.9) instead truncates an existing floating-point value toward zero, which can silently discard information.',
      'Separate parsing from business validation. int("-4") is a successful conversion, but a hospital cannot accept a negative number of appointment slots. Treat units explicitly: 120 might mean seconds, minutes or currency minor units. Do not fix malformed input by silently deleting characters unless that normalization is part of the documented format.'
    ] },
    { heading: 'Truthiness is a rule, not a natural-language parser', paragraphs: [
      'bool(value) follows Python’s truth-value rules. Zero, empty containers, the empty string and None are false; most other values are true. Both bool("False") and bool("0") are True because those strings are nonempty. For a form that accepts yes/no text, define the accepted spellings and compare normalized strings. Reject an unrecognized response rather than guessing.',
      'The operators and and or return one of their operands; they do not always return bool objects. For example, a fallback expression entered_name or "Guest" returns a string. This can be useful, but it also treats every false value, including numeric zero, as absent. To distinguish missing data from zero, check value is None. None is a singleton conventionally used for “no value”, not the text "None".'
    ] },
    { heading: 'Report expected input errors narrowly', paragraphs: [
      'An invalid numeric string raises ValueError. A try block can attempt conversion, and except ValueError can provide a useful response when that expected conversion fails. Later lessons explain exception handling in full. Keep unrelated calculations outside the try block so a programming defect is not mistaken for a user input error.',
      'Do not use eval to convert submitted text into Python objects: evaluation can execute instructions. Use a constructor or a format-specific parser. Floating-point conversions retain the precision limitations from the arithmetic lesson. Accepting nan or infinity may be possible for float, but many business calculations require finite values and must check that condition explicitly.'
    ] }
  ],
  { problem: 'A course registration imports a submitted seat count. It must be a positive whole number; malformed and nonpositive counts need different messages.', steps: ['Parse the text as an integer, catching only its expected ValueError.','When parsing succeeds, validate the count separately.','Return a result without changing a decimal string into an integer by silent rounding.'], code: 'def seats(text):\n    try:\n        count = int(text)\n    except ValueError:\n        return "Enter a whole number"\n    return count if count > 0 else "Enter a positive count"\nprint(seats("12"))\nprint(seats("12.5"))\nprint(seats("0"))\nprint(bool("False"))', expect: '12\nEnter a whole number\nEnter a positive count\nTrue', explanation: 'A function groups these steps and returns one result; the functions lesson develops that notation. Converting "12.5" fails rather than losing its fractional part. Zero parses correctly but violates the positive-count rule. The final line demonstrates that truthiness does not parse Boolean words.' },
  ['Assuming input() returns an integer can concatenate text or raise a type error during arithmetic.','Using bool("False") to parse a form incorrectly records True. Define an accepted-value table.','Using int(float(text)) to accept counts can truncate a fractional input that should have been rejected.'],
  ['Parsing and business validation are separate steps.','A successful conversion does not establish a valid range or unit.','Use narrow error handling and explicit Boolean parsing instead of eval or truthiness guesses.'], ['functions','types','errors'], [2,3]);

add('py-collections', 'm2.c1', 'Choosing a collection for the data contract',
  'Applications often hold many values at once: ordered invoice lines, a geographic coordinate, a set of enrolled learner IDs or prices indexed by product code. Python’s list, tuple, set and dict have different contracts. Choose by the operations and constraints the application needs, not by which punctuation is shortest.',
  [
    { heading: 'Order, repetition and mutability', paragraphs: [
      'A list, written with square brackets, is an ordered mutable sequence. It supports positions, slices, duplicates and appending. Use a list for an order’s line items when order and repeated values matter. A tuple is an ordered immutable sequence; a comma creates the tuple, so a single-element tuple is (value,). A tuple can hold mutable objects, so immutable outer structure does not make everything inside deeply immutable.',
      'A set holds unique hashable elements. It supports membership, union, intersection and difference. A set does not provide a stable sequence-index contract; never depend on its printed order. Write set() for an empty set, since {} creates an empty dict. A list cannot be a set element because it is mutable and unhashable. A tuple can be hashable only when its elements are hashable too.'
    ] },
    { heading: 'A dictionary represents a mapping', paragraphs: [
      'A dict associates unique hashable keys with values. Looking up a product by code is a mapping problem, so prices["A17"] is clearer than searching a pair of unrelated lists. Insertion order is preserved in modern Python, but replacing a key’s value does not create a second copy of that key. A value may be any object, including another collection.',
      'Membership in a dict checks keys, not values. Use key in mapping before a required lookup, or get(key, default) when a missing key has an explicit fallback. Do not hide a missing required value with a default that can be mistaken for real data. For example, a missing exam score should not automatically become zero. Distinguish missing values from measured values.'
    ] },
    { heading: 'Match the collection to the next operation', paragraphs: [
      'If order and duplicates matter, begin with a list. If you need a fixed record-shaped sequence, a tuple may express that intent. If uniqueness and membership dominate, use a set. If values must be addressed by a meaningful key, use a dict. These are design starting points rather than rigid bans on other uses. Convert between collections only when losing properties is acceptable.',
      'For example, set(registrations) removes duplicate registrations but also loses sequence meaning. dict.fromkeys(registrations) can preserve first-seen order while deduplicating hashable items, and list(...) extracts those keys as a sequence. This does not count repetitions; a separate tally is needed if counts matter. A collection is not a substitute for validating that its individual values satisfy the application’s contract.'
    ] }
  ],
  { problem: 'An LMS receives learner IDs from two event registrations and needs the IDs registered for both, plus a named capacity lookup.', steps: ['Represent each event’s unique IDs as a set.','Intersect the sets; sort only for deterministic display, not because a set itself is ordered.','Keep capacity in a dictionary keyed by event code.'], code: 'morning = {101, 102, 103}\nevening = {102, 103, 104}\ncapacity = {"morning": 30, "evening": 20}\nprint(sorted(morning & evening))\nprint(capacity["morning"])\nprint("morning" in capacity)', expect: '[102, 103]\n30\nTrue', explanation: 'The intersection contains only IDs present in both events. sorted returns a new ordered list for display. Dictionary membership confirms the key exists; it does not test whether 30 is a stored value.' },
  ['Using {} for an empty set creates a dictionary instead.','Converting ordered repeated records into a set loses information.','Assuming a tuple containing a list makes the inner list immutable confuses outer and inner objects.'],
  ['Select a collection by order, uniqueness, mutability and lookup needs.','Dictionary keys and set elements must be hashable.','Preserving order and counting duplicates are different requirements.'], ['datastructures','types'], [7,8,9]);

add('py-mutation', 'm2.c2', 'Tracing mutation, copies and missing keys',
  'Two dashboard components may receive what appears to be the same list of pending orders. If one component removes an item and the other changes unexpectedly, the issue may be shared state. Python names refer to objects. Assignment, mutation and copying are different operations, and tracing those differences prevents data loss and confusing side effects.',
  [
    { heading: 'Draw names pointing to objects', paragraphs: [
      'After first = ["A", "B"] and second = first, both names refer to the same list object. second.append("C") changes that object, so first also observes the new element. This is aliasing. Reassigning second = [] instead binds second to a different list and leaves the first list unchanged. Mutation changes an object; rebinding changes which object a name refers to.',
      'List append adds one object, while extend iterates over an input and adds its elements. These methods mutate the list and return None. Writing items = items.append(new_item) therefore loses the list binding by replacing it with None. Use items.append(new_item) as a statement, or explicitly construct a new list when a nonmutating operation is intended.'
    ] },
    { heading: 'Know which level a copy duplicates', paragraphs: [
      'list.copy(), a full list slice and list(existing_list) make a shallow outer copy. The new list can grow independently, but nested mutable objects remain shared. If records contains dictionaries, records.copy()[0]["status"] = "sent" changes the same nested dictionary held by records. A shallow copy is sufficient only when its shared inner values are immutable or shared mutation is intended.',
      'copy.deepcopy can recursively duplicate supported object graphs, tracking already-copied objects to handle cycles. It is not always the right design: some objects represent external resources, and copying them cannot duplicate the underlying business entity. Often the clearer correction is to create a new record with the changed fields and document ownership of mutable state.'
    ], diagram: 'first ──┐\n        ├──> shared list ──> shared nested record\nsecond ─┘\ncopy ──────> new list ─────> same nested record' },
    { heading: 'Update mappings deliberately', paragraphs: [
      'Assigning mapping[key] = value inserts a new key or replaces its value. pop removes a key and returns its value, optionally using an explicit fallback. get returns a value without inserting the key. defaultdict and setdefault can create entries as part of access patterns; use them only when that insertion is intended. Updating an existing key preserves its position in dictionary insertion order.',
      'Avoid adding or removing dictionary keys while directly iterating over its live view. Build a list of keys to remove first or construct a new filtered dictionary. Likewise, removing list elements while iterating forward can skip the next element because positions shift. A comprehension can express a nonmutating filter clearly. These rules are about predictable iteration, not about blocking every change to a value.'
    ] }
  ],
  { problem: 'A support dashboard wants to add a note to a draft ticket without editing the original ticket record.', steps: ['Create a new outer list and a new dictionary for its first ticket; an outer list copy alone would still share the ticket.','Mutate only the new dictionary.','Show both values to confirm the intended separation.'], code: 'tickets = [{"id": 7, "status": "open"}]\ndraft = [dict(tickets[0])]\ndraft[0]["status"] = "reviewed"\nprint(tickets[0]["status"])\nprint(draft[0]["status"])\nprint(tickets is draft)', expect: 'open\nreviewed\nFalse', explanation: 'dict(tickets[0]) creates a new shallow dictionary; its values here are immutable integers and strings. That is sufficient for this record. If it contained a nested list of notes, that nested list would still need its own ownership/copy decision. is checks object identity, while == compares values.' },
  ['Treating assignment as a copy lets one consumer unexpectedly mutate another consumer’s data.','Using the return value of append or dict.update as the updated collection replaces a name with None.','Assuming a shallow copy duplicates every nested object produces hidden sharing.'],
  ['Trace object identity separately from equal values.','Shallow copies duplicate the outer collection, not a whole object graph.','Design update and iteration rules so that mutation is intentional.'], ['datastructures','types'], [7,9]);

add('py-comprehensions', 'm2.c3', 'Filtering and transforming records with comprehensions',
  'An inventory export needs selected records in a different shape: keep products with low stock and report their codes in lowercase. A comprehension is a compact way to build a new collection by iterating, optionally filtering, and calculating an output expression. Learn the execution order first; compact syntax is useful only when it makes the rule easier to inspect.',
  [
    { heading: 'Read a comprehension in execution order', paragraphs: [
      'A for clause binds a name to each element of an iterable, which is an object that can supply values one at a time. In [price * 2 for price in prices], first consider for price in prices, then evaluate price * 2 for that element. The expression before for is not evaluated just once. A final if condition filters elements before the output expression runs.',
      'An ordinary loop can express the same transformation: start an empty result list, visit each input, test the condition and append a computed value. Use that expanded form while learning. An empty input naturally produces an empty result. A list comprehension creates its result eagerly, so it consumes memory proportional to the output size.'
    ] },
    { heading: 'Distinguish filtering from choosing an output value', paragraphs: [
      'In [x for x in counts if x > 0], the final if omits nonpositive elements. In ["ready" if x > 0 else "empty" for x in counts], a conditional expression chooses one output for every input element. Moving the condition changes both the meaning and possibly the length. The output expression can call a function, but avoid hidden side effects that make a “build a result” expression unexpectedly modify other state.',
      'Braces create a set comprehension for unique results, or a dictionary comprehension with key: value expressions. Duplicate dictionary keys replace an earlier value, so a comprehension is not a safe aggregation unless the collision rule is intended. A generator expression, written with parentheses, yields values lazily and is often suitable as input to sum. A generator is consumed as it is iterated, so do not assume it can be restarted.'
    ] },
    { heading: 'Keep transformations understandable', paragraphs: [
      'A comprehension may contain multiple for clauses; they execute in the same order as nested loops. This is useful for flattening a small nested structure but can accidentally create a Cartesian product. If a transformation needs error recovery, multiple named intermediate values or complicated branching, a normal loop is usually easier to debug and test.',
      'The iteration variable of a comprehension does not leak into the surrounding scope in Python 3. Inner mutable objects may still be shared when the output expression returns an existing object rather than a copy. Building [row for row in rows] makes a new list of the same row objects; it does not duplicate each row. The previous lesson’s ownership rules still apply.'
    ] }
  ],
  { problem: 'A warehouse wants codes for products with fewer than three units in stock, plus a restock quantity mapping.', steps: ['Represent the sample products as dictionaries in a list.','Filter by stock count and transform the code for a report.','Build a second mapping that calculates how many units are needed to reach five.'], code: 'products = [{"code": "A1", "stock": 2}, {"code": "B2", "stock": 7}]\nlow = [p["code"].lower() for p in products if p["stock"] < 3]\nrestock = {p["code"]: 5 - p["stock"] for p in products if p["stock"] < 3}\nprint(low)\nprint(restock)', expect: "['a1']\n{'A1': 3}", explanation: 'Only A1 satisfies the filter. Its display code becomes lowercase, while the dictionary keeps the original key and records a derived quantity. The input product dictionaries are read, not changed. The number five is the hypothetical warehouse’s target, not a Python rule.' },
  ['Placing an if filter where a conditional expression is required changes which elements exist.','Returning the same mutable row objects does not create independent records.','Hiding a long business workflow in nested comprehension clauses makes errors harder to locate.'],
  ['Follow iteration, filtering, then output expression.','Choose list, set, dict or generator construction by the output contract.','Use a normal loop when the transformation needs several explicit steps.'], ['datastructures','controlflow'], [7]);

add('py-control-flow', 'm3.c1', 'Tracing decisions and loops without skipped cases',
  'A fulfillment job processes shipments in order. It must skip canceled shipments, stop at a safety limit and total only accepted packages. These are control-flow decisions: statements that determine which instructions run and how often. Trace the state after each iteration instead of trying to infer the result from the visual shape of the code.',
  [
    { heading: 'Conditions select one branch', paragraphs: [
      'An if statement evaluates a condition and executes its indented block when the condition is true. elif tests the next condition only when earlier branches were not taken. else handles the remaining case. Comparisons include ==, !=, <, <=, > and >=. Use == for equality; assignment with = is a different operation. Conditions may combine tests with and, or and not; add parentheses when they improve clarity.',
      'Order matters for overlapping conditions. If every total above 100 also qualifies for “above 50”, put the more specific high threshold first when those branches must be exclusive. Chained comparisons such as 0 <= score <= 100 express an inclusive range. A branch that validates a range should reject invalid values, rather than silently sending them through a default success case.'
    ] },
    { heading: 'for iterates values; while repeats a condition', paragraphs: [
      'for item in iterable obtains each value in turn. range(stop) produces integers starting at zero and excluding stop; range(start, stop, step) changes those choices. A negative step must move toward the stop bound to produce values. range itself is a compact range object, not an eagerly constructed list. enumerate supplies an index and value together when both are needed.',
      'while condition repeats while its condition stays true, so something must eventually change the state or break the loop. An off-by-one error often comes from confusing an excluded range endpoint with an inclusive business requirement. Write down the intended first and last values. Test zero iterations and a single iteration, not just a long sample.'
    ] },
    { heading: 'break, continue and loop else have distinct effects', paragraphs: [
      'continue skips the rest of the current iteration and begins the next one. break exits the nearest enclosing loop, not every surrounding loop. A loop’s else block runs when the loop finishes without break, including when there were no iterations. It is not the same as an if statement’s else and does not mean “the last item failed”.',
      'Use a small trace table with columns for the current item, decision and running total. This makes it apparent whether an update happens before or after a continue or break. Prefer explicit names over modifying the input list during iteration. For nested searches, a helper function returning a result can be clearer than coordinating flags across multiple break statements.'
    ] }
  ],
  { problem: 'A synthetic shipment batch skips canceled entries represented by zero and stops at a negative safety marker. Sum valid package counts before the marker.', steps: ['Initialize the total before iterating.','Skip zero before adding; break on the negative marker.','Update only accepted counts and display the final total.'], code: 'counts = [2, 0, 3, -1, 9]\ntotal = 0\nfor count in counts:\n    if count == 0:\n        continue\n    if count < 0:\n        break\n    total += count\nprint(total)', expect: '5', explanation: 'Two is added, zero skips the update, and three is added. The negative marker exits the loop, so nine is never processed. A trace is [2 → total 2], [0 → skip], [3 → total 5], [-1 → stop]. The rule is original to this example; negative values are not generally special in Python loops.' },
  ['Updating a running total before a continue includes a record that should have been skipped.','Expecting break to leave two nested loops confuses its nearest-loop scope.','Forgetting to update a while condition can create an infinite loop.'],
  ['Indentation and statement order determine which updates occur.','range excludes its stop value.','A loop else executes after normal exhaustion, not after break.'], ['controlflow','types'], [5,6]);

add('py-functions', 'm3.c2', 'Designing functions with clear argument contracts',
  'A pricing calculation used by an invoice page and an export job should have one explicit interface. A function groups a calculation, gives inputs meaningful names and returns a result. It can be tested independently from user input and display. A clear function contract explains accepted arguments, side effects, return value and exceptional cases.',
  [
    { heading: 'Parameters describe inputs; return supplies a result', paragraphs: [
      'def introduces a function definition. The names in its signature are parameters; values supplied at a call are arguments. Positional arguments match parameter order, and keyword arguments match parameter names. A docstring is an optional string immediately inside the function body that describes its contract. Calling the function runs its body; defining it does not perform the calculation in that body.',
      'return exits the current function and supplies a value to the caller. Reaching the end without return supplies None. print displays text but does not replace return: a caller cannot add a printed number to another value. Keep computation and presentation separate so the same function can serve a web page, a batch process and a test.'
    ] },
    { heading: 'Defaults and explicit call conventions', paragraphs: [
      'A default lets a caller omit an argument: def price(amount, rate=0.1) supplies a rate when none is given. Required parameters normally precede defaulted positional-or-keyword parameters. Supplying the same parameter both positionally and by keyword is an error. An unknown keyword is also an error unless the signature explicitly accepts additional named arguments.',
      'A bare * in a signature makes following parameters keyword-only, such as def price(amount, *, rate=0.1). This can make a potentially confusing business choice explicit. A / can mark preceding parameters positional-only; recognize it when reading library signatures, but do not add it to every beginner function without a reason. Default expressions are evaluated when def executes, not on every call; the next lesson explores the mutable-default hazard.'
    ] },
    { heading: 'Use variable arguments only for a real requirement', paragraphs: [
      '*args collects additional positional arguments into a tuple. **kwargs collects additional keyword arguments into a dictionary. These names are conventions; the stars determine the behavior. At a call, *iterable unpacks positional values and **mapping unpacks keyword values. A mapping passed with ** must have string keys suitable for the call’s parameter names.',
      'An interface that accepts every possible keyword can hide misspelled configuration. Prefer named parameters for a stable business contract and validate supported extra fields if flexibility is needed. Do not silently ignore unexpected arguments. Functions can return a tuple of related values, but several unrelated results may suggest the function is doing too much.'
    ] }
  ],
  { problem: 'A billing helper totals several whole-unit charges and applies an explicit discount. It must return a value so another calculation can use it.', steps: ['Collect the charge amounts with *charges.','Make discount keyword-only by placing it after the starred parameter.','Return the total minus discount, then format the returned value outside the helper.'], code: 'def invoice_total(*charges, discount=0):\n    """Return total whole-unit charges minus a whole-unit discount."""\n    return sum(charges) - discount\n\ncharges = [30, 20]\nresult = invoice_total(*charges, discount=5)\nprint(result)\nprint(invoice_total(10))', expect: '45\n10', explanation: 'The call unpacks the list into two positional charges. discount is matched by name and is not included in the charges tuple. The helper returns 45, which the caller prints. An omitted discount is zero. Real billing would additionally validate signs, currency units and authorization to apply discounts.' },
  ['Printing a value when the caller expects a return value leaves the caller with None.','Passing an argument twice, once positionally and once by keyword, raises TypeError.','Accepting arbitrary **kwargs without checking supported fields can hide spelling mistakes.'],
  ['Specify inputs, outputs and side effects in a function contract.','Defaults reduce repetition, while keyword-only choices can improve clarity.','Unpacking at a call is different from collecting arguments in a definition.'], ['controlflow','functions'], [10,11]);

add('py-scope', 'm3.c3', 'Understanding scope and safe default state',
  'A helper that remembers values from a previous request can leak one learner’s state into another learner’s response. Python’s scope and default-argument rules explain how that can happen even in a short function. The solution is to make ownership and lifetime of state explicit, not to add more global variables.',
  [
    { heading: 'Find the binding used by a name', paragraphs: [
      'Within a function, an ordinary name is searched in local, enclosing-function, module-global and built-in scopes, commonly summarized as LEGB. A function that only reads a name may use a surrounding binding. An assignment to a name anywhere in the function normally makes it local throughout that function, unless declared global or nonlocal.',
      'Reading such a local name before it has received a value raises UnboundLocalError, even if a global variable has the same name. global tells a function to rebind a module-level name; nonlocal refers to an existing binding in an enclosing function scope. Use these declarations only when shared rebinding is part of the design. Passing an input and returning a result is often simpler to reason about.'
    ] },
    { heading: 'Defaults are evaluated when the definition runs', paragraphs: [
      'In def collect(item, bucket=[]), the list expression is evaluated once when the definition executes. Calls that omit bucket reuse that same list, so appending in one call changes what a later call observes. This is sometimes intentional caching, but it is a dangerous accidental default for per-request data.',
      'Use None as a sentinel when a fresh collection is required for each omitted argument. Inside the function, test bucket is None and create a list there. Do not use bucket = bucket or [] if an explicitly supplied empty list must be mutated, because an empty list is false and would be replaced. Explicitly supplied mutable objects still belong to a caller-visible ownership contract.'
    ] },
    { heading: 'Closures retain bindings, not frozen loop values', paragraphs: [
      'An inner function can refer to names in an enclosing function. Such a closure can outlive the call that created it. In a loop that appends lambdas referring to the loop variable, later calls normally see the variable’s final value rather than a separate snapshot from each iteration. A lambda is a small function expression, not a special rule for capturing values.',
      'For a genuinely fixed per-function value, an immutable default parameter can deliberately bind the current value during creation, or use a helper function that creates a separate enclosing binding. Distinguish this deliberate binding from accidentally shared mutable defaults. Avoid shadowing built-ins such as list or sum, which makes later code that expects those functions confusing.'
    ] }
  ],
  { problem: 'An LMS helper should create a fresh learner-specific list when no list is supplied, while honoring a caller’s explicit empty list.', steps: ['Use None as the default marker, rather than allocating a list in the signature.','Create a list only when the argument is exactly None.','Demonstrate two independent omitted-argument calls and one explicitly shared list.'], code: 'def remember(item, bucket=None):\n    if bucket is None:\n        bucket = []\n    bucket.append(item)\n    return bucket\n\nprint(remember("A"))\nprint(remember("B"))\nshared = []\nremember("C", shared)\nprint(shared)', expect: "['A']\n['B']\n['C']", explanation: 'Each omitted-argument call executes a fresh list creation. The explicit shared list is not replaced, so its caller can observe the append. The identity check is None distinguishes absence from an intentionally supplied empty collection.' },
  ['A mutable default can retain values across calls and mix separate users’ work.','Assigning to a global-looking name inside a function normally makes it local, which may cause UnboundLocalError on an earlier read.','Expecting loop-created lambdas to freeze a changing loop variable leads to late-binding surprises.'],
  ['Scope determines which binding an expression reads.','Default values are created at definition time.','Use a None sentinel for fresh per-call mutable state, and document explicit sharing.'], ['controlflow','types'], [10,12]);

add('py-exceptions', 'm4.c1', 'Handling failures without hiding defects',
  'A support-ticket importer may encounter malformed counts even when the surrounding program is correct. An exception signals that an operation could not complete normally. Good handling makes expected failures understandable while keeping unexpected defects visible. A broad “catch everything and continue” policy can silently turn lost data into an apparent success.',
  [
    { heading: 'Catch the failure you can actually recover from', paragraphs: [
      'When an exception is raised, normal execution stops and Python searches outward for a matching except clause. A try block contains the operation that may fail; except ValueError can handle an invalid conversion. Other errors should propagate unless the function has a meaningful recovery policy. Multiple exception types can be grouped in a tuple when the same recovery really applies.',
      'Keep the try block narrow. If a conversion and a database write are inside one broad handler, a database defect might be reported as “please enter a number”. That message would be false and could hide lost work. Do not expose sensitive internal data in user-facing errors. Give the user a useful action and preserve enough protected diagnostic context for maintainers.'
    ] },
    { heading: 'Use else and finally for different purposes', paragraphs: [
      'A try statement’s else block runs when its try block finishes without an exception. It is a useful place for success-only work that should not be mistaken for a parsing failure. finally runs when control leaves the try statement under normal execution, a handled or propagating exception, return, break or continue. It is commonly used for cleanup; a context manager is usually clearer for a resource that supports one.',
      'Do not return from finally unless overriding earlier control flow is explicitly intended. A return there can replace a pending exception or an earlier return value. “finally always runs” is shorthand for Python control flow, not a promise after a power loss or forced process termination. Durable data still requires an appropriate persistence design.'
    ] },
    { heading: 'Raise useful errors at the right boundary', paragraphs: [
      'A function can raise ValueError when an argument has the correct broad type but an invalid value. A bare raise inside a handler re-raises the current exception. Raising a new exception from the original, as in raise ImportError("...") from exc, preserves an explicit cause chain. Prefer an existing appropriate exception type unless callers need a distinct category.',
      'Exceptions are not a substitute for every ordinary branch. An empty search result may be a normal business outcome, while an unreadable required file is a failure. Define that contract. Catching Exception does not include every BaseException subclass, such as KeyboardInterrupt; this separation lets interruption and process-exit signals propagate rather than being treated as routine application errors.'
    ] }
  ],
  { problem: 'A ticket importer must report a bad integer without skipping its cleanup message, and print a success count only when parsing worked.', steps: ['Place only int conversion in the try block.','Print a helpful message for ValueError; use else for the valid count.','Use finally to demonstrate common cleanup control flow.'], code: 'def import_count(text):\n    try:\n        count = int(text)\n    except ValueError:\n        print("Invalid count")\n    else:\n        print(f"Parsed {count}")\n    finally:\n        print("Import step finished")\n\nimport_count("3")\nimport_count("bad")', expect: 'Parsed 3\nImport step finished\nInvalid count\nImport step finished', explanation: 'The first conversion succeeds, so else prints the count. The second fails, so except prints an input message. Both calls reach finally. This example does not claim a durable import occurred; it only demonstrates the control-flow contract.' },
  ['Catching every exception and returning success hides failures rather than recovering from them.','Putting unrelated operations in a conversion handler can misdiagnose a system defect as bad input.','Returning from finally can suppress the exception a caller needed to see.'],
  ['Handle expected errors narrowly and let unexpected failures remain visible.','else is success-only; finally handles exit cleanup.','Error wording should describe what actually happened without exposing secrets.'], ['errors','controlflow'], [3,15]);

add('py-files', 'm4.c2', 'Reading text and CSV with explicit resource ownership',
  'A learning platform exports course enrollments for another department. The export is a file with an agreed format, not simply whatever print happens to display. Reliable file work needs a mode, encoding, lifetime and parser. This lesson teaches local text and CSV handling with context managers; it does not require access to real student data.',
  [
    { heading: 'Opening a file creates a resource contract', paragraphs: [
      'open(path, mode, encoding=...) returns a file object for a named path. Text mode decodes and encodes characters; binary mode reads and writes bytes. Specify an encoding such as UTF-8 for a defined interchange format rather than depending on a machine’s default. Mode r reads an existing file, w creates or truncates a file, a appends, and x requires creating a new file without replacing an existing one.',
      'Use with open(...) as handle: so the file is closed when the block exits, including when an exception propagates. Closing is about resource cleanup, not about guaranteeing a transaction across multiple files. A write followed by a process crash may require atomic replacement and explicit durability measures in a production application. For this lesson, write only synthetic files in an isolated working directory.'
    ] },
    { heading: 'Stream records and respect the input format', paragraphs: [
      'Iterating over a text file reads its lines progressively instead of loading the entire file at once. read() can load everything, while read(size) limits a read. A line commonly retains its newline; remove only the characters your format says are separators. strip() removes more than just a newline and can unintentionally remove meaningful leading or trailing whitespace.',
      'CSV supports delimiters, quoted fields and embedded delimiters or newlines. Splitting each line on a comma does not implement the CSV format correctly. Use csv.reader or csv.DictReader to parse it and csv.writer or csv.DictWriter to produce it. Open CSV text files with newline="" so the csv module controls newline handling. Define the delimiter, header names, required columns and missing-value policy with the receiving system.'
    ] },
    { heading: 'Treat file data as untrusted input', paragraphs: [
      'CSV readers yield text fields; a quantity column still needs conversion and validation. A missing header should be reported rather than silently read from a different column. Row length, size and encoding errors can also require a deliberate policy. When a CSV is intended for a spreadsheet, cells beginning with formula characters may need a downstream-specific neutralization policy; CSV quoting alone is not formula-injection protection.',
      'Never let an arbitrary submitted filename select any server path. A web upload belongs in an application-controlled location with a generated storage name and appropriate permissions. These are defensive boundary concerns separate from learning Python’s file API. The example uses one known filename inside the sandbox and reads back exactly the format it wrote.'
    ] }
  ],
  { problem: 'Export two synthetic enrollments, including a learner display name containing a comma, and read them back without splitting that name into two fields.', steps: ['Use a context manager and UTF-8 text encoding for the output file.','Write a header and rows with csv.writer, which quotes a comma-containing field correctly.','Read using DictReader and address a column by its header name.'], code: 'import csv\nwith open("enrollments.csv", "w", encoding="utf-8", newline="") as out:\n    writer = csv.writer(out)\n    writer.writerow(["id", "name"])\n    writer.writerow([101, "Learner, One"])\n    writer.writerow([102, "Learner Two"])\nwith open("enrollments.csv", encoding="utf-8", newline="") as source:\n    rows = list(csv.DictReader(source))\nprint(rows[0]["name"])\nprint(len(rows))\nprint(type(rows[0]["id"]).__name__)', expect: 'Learner, One\n2\nstr', explanation: 'The comma remains inside a single name field because the writer and reader implement CSV quoting. The header is used as dictionary keys and is not counted as a data row. The id is still a string after CSV parsing; an application needing numeric IDs must validate and convert it separately.' },
  ['Opening an existing file with w truncates its previous contents before writing.','Splitting CSV on commas breaks quoted fields and embedded separators.','Assuming a CSV numeric-looking field is already an int skips required parsing and validation.'],
  ['Specify mode, encoding and lifetime explicitly.','Use the CSV library for CSV, with newline="" and an agreed schema.','A context manager closes resources but does not validate data or create multi-file transactions.'], ['inputoutput','csv','errors'], [15]);

add('py-modules', 'm4.c3', 'Organizing code into modules and using the standard library',
  'As a small script grows, importing reusable functions is clearer than copying them between files. A module is a namespace containing definitions, usually loaded from a Python file. A package organizes related modules. The standard library provides tested tools for common tasks, so the first design question should often be which existing tool matches the requirement.',
  [
    { heading: 'Imports bind names and can execute code', paragraphs: [
      'import math binds the module name, so math.sqrt(9) identifies the namespace explicitly. from math import sqrt binds sqrt directly in the importing module. An alias, such as import statistics as stats, changes the local binding, not the imported module’s public name. Avoid import * in application code because it hides where names came from and can overwrite unrelated bindings.',
      'When a module is first imported, its top-level code executes and its module object is normally cached in sys.modules. A later import in the same process typically reuses that object rather than rerunning initialization. Keep top-level side effects small: importing a helper should not unexpectedly send email or alter a database. If two modules import each other while partially initialized, a circular dependency can expose missing definitions; reorganize shared contracts rather than adding fragile import ordering.'
    ] },
    { heading: 'Separate reusable definitions from script entry', paragraphs: [
      'A file run as the entry script has __name__ equal to "__main__". Guard command-line work with if __name__ == "__main__": so importing the module can reuse its definitions without running that command-line workflow. This does not suppress all top-level execution: definitions, imports and any unguarded statements still execute on first import.',
      'An ordinary package can use an __init__.py file; Python also supports namespace packages without that file in suitable import configurations. Keep the beginner layout simple, with clear module names and absolute imports within a project. Do not call your file csv.py or statistics.py when you intend to import the standard-library module of the same name, because local import search paths can shadow it.'
    ] },
    { heading: 'Choose a library by its semantic contract', paragraphs: [
      'math provides mathematical functions, statistics computes descriptive statistics, csv handles tabular interchange, pathlib represents filesystem paths, and collections supplies specialized containers. Read the function’s contract, including empty-input behavior and expected types. statistics.mean on an empty sequence raises StatisticsError; an empty dataset is not automatically a measured mean of zero.',
      'The standard library ships with Python, while third-party distributions are installed separately and may expose modules with different names. Virtual environments isolate third-party dependencies for projects. Pin compatible dependencies and follow their version-specific documentation. Never install or import an untrusted package merely because its name resembles a desired library. This course’s executable examples use only the standard library.'
    ] }
  ],
  { problem: 'A support dashboard wants the average of three synthetic response times and the two most common issue categories, without implementing aggregation algorithms from scratch.', steps: ['Import the specific standard-library tools whose contracts fit the calculations.','Use mean for numeric observations and Counter for category frequencies.','Display results explicitly; keep data acquisition separate from aggregation.'], code: 'from statistics import mean\nfrom collections import Counter\nresponse_minutes = [10, 20, 30]\nissues = ["login", "billing", "login"]\nprint(mean(response_minutes))\nprint(Counter(issues).most_common(2))', expect: "20\n[('login', 2), ('billing', 1)]", explanation: 'mean computes the arithmetic mean of the three numeric observations. Counter counts occurrences, and most_common returns category/count pairs in descending frequency order. A real dashboard would define how missing or invalid observations are handled instead of silently replacing them with zero.' },
  ['Naming a local script after a standard-library module can import the wrong file.','Assuming the main guard prevents all import-time work overlooks unguarded top-level statements.','Copying an aggregation algorithm without checking existing library tools adds avoidable maintenance work.'],
  ['Imports bind names and may execute module initialization.','Keep reusable functions separate from script-only side effects.','Use documented standard-library contracts and handle missing or empty data explicitly.'], ['modules','functions'], [12,15]);

